def find_pairs(nums, target):
    seen = {}
    pairs = set()
    for num in nums:
        complement = target - num
        if complement in seen:
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen[num] = True
    return [list(p) for p in pairs]

print(find_pairs([1, 2, 3, 4, 5], 6))  # [[1, 5], [2, 4]]

