import time

class SessionCache:
    def __init__(self):
        self.store = {}

    def set(self, user_id, data, ttl_seconds=1800):
        self.store[user_id] = {'data': data, 'expires_at': time.time() + ttl_seconds}

    def get(self, user_id):
        entry = self.store.get(user_id)
        if entry is None:
            return None
        if time.time() > entry['expires_at']:
            del self.store[user_id]
            return None
        return entry['data']

    def cleanup(self):
        now = time.time()
        expired = [uid for uid, entry in self.store.items() if entry['expires_at'] <= now]
        for uid in expired:
            del self.store[uid]

cache = SessionCache()
cache.set('u1', {'role': 'admin'})
print(cache.get('u1'))  # {'role': 'admin'}
cache.cleanup()

